/// Shows the real YouTube thumbnail for a lesson's video so learners can see
/// what they're about to watch, instead of a generic placeholder card.
class _VideoThumbnailPreview extends StatelessWidget {
  const _VideoThumbnailPreview({
    required this.videoId,
    required this.tint,
    required this.onTap,
  });

  final String videoId;
  final Color tint;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(18),
      child: AspectRatio(
        aspectRatio: 16 / 9,
        child: GestureDetector(
          onTap: onTap,
          child: Stack(
            fit: StackFit.expand,
            children: <Widget>[
              Image.network(
                'https://i.ytimg.com/vi/$videoId/hqdefault.jpg',
                fit: BoxFit.cover,
                loadingBuilder: (BuildContext context, Widget child,
                    ImageChunkEvent? progress) {
                  if (progress == null) return child;
                  return Container(
                    color: tint.withOpacity(0.4),
                    alignment: Alignment.center,
                    child: const SizedBox(
                      width: 26,
                      height: 26,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white),
                    ),
                  );
                },
                errorBuilder: (BuildContext context, Object error,
                        StackTrace? stackTrace) =>
                    Container(
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: <Color>[
                        tint.withOpacity(0.96),
                        Color.alphaBlend(
                            tint.withOpacity(0.58),
                            Theme.of(context).colorScheme.surface),
                      ],
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                    ),
                  ),
                ),
              ),
              DecoratedBox(
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    colors: <Color>[
                      Colors.black.withOpacity(0.05),
                      Colors.black.withOpacity(0.32),
                    ],
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                  ),
                ),
              ),
              Center(
                child: Container(
                  width: 56,
                  height: 56,
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(0.45),
                    shape: BoxShape.circle,
                    border: Border.all(color: Colors.white.withOpacity(0.8)),
                  ),
                  child: const Icon(
                    Icons.play_arrow_rounded,
                    size: 32,
                    color: Colors.white,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _QuizQuestionCard extends ConsumerStatefulWidget {
  const _QuizQuestionCard({
    required this.lessonId,
    required this.question,
    required this.index,
    required this.tint,
  });

  final String lessonId;
  final LessonQuestion question;
  final int index;
  final Color tint;

  @override
  ConsumerState<_QuizQuestionCard> createState() => _QuizQuestionCardState();
}

class _QuizQuestionCardState extends ConsumerState<_QuizQuestionCard> {
  int? _selectedIndex;
  bool _revealed = false;
  bool? _isCorrect;
  bool _skipped = false;

  @override
  Widget build(BuildContext context) {
    final ThemeData theme = Theme.of(context);
    final AppLanguage language = ref.watch(appLanguageProvider);

    return AppCard(
      color: theme.colorScheme.surfaceContainerHighest,
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            Row(
              children: <Widget>[
                Container(
                  width: 36,
                  height: 36,
                  decoration: BoxDecoration(
                    color: AppColors.chipBackgroundFor(
                      widget.tint,
                      isDark: theme.brightness == Brightness.dark,
                      surface: theme.colorScheme.surfaceContainerHighest,
                    ),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Center(
                    child: Text(
                      '${widget.index}',
                      style: theme.textTheme.labelLarge?.copyWith(
                        fontWeight: FontWeight.w800,
                        color: AppColors.chipForegroundFor(
                          isDark: theme.brightness == Brightness.dark,
                          onSurface: theme.colorScheme.onSurface,
                        ),
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Text(
                    widget.question.prompt,
                    style: theme.textTheme.titleMedium
                        ?.copyWith(fontWeight: FontWeight.w800),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 14),
            ...widget.question.options.asMap().entries.map(
                  (MapEntry<int, String> entry) => Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: RadioListTile<int>(
                      value: entry.key,
                      groupValue: _selectedIndex,
                      onChanged: _revealed
                          ? null
                          : (int? value) {
                              setState(() => _selectedIndex = value);
                            },
                      contentPadding: const EdgeInsets.symmetric(horizontal: 0),
                      title: Text(entry.value),
                      dense: true,
                    ),
                  ),
                ),
            const SizedBox(height: 6),
            if (_revealed)
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: (_isCorrect ?? false)
                      ? const Color(0xFFE8F4D8)
                      : const Color(0xFFFFEBCF),
                  borderRadius: BorderRadius.circular(18),
                ),
                child: Text(
                  _skipped
                      ? language.tr(
                          en: 'Skipped for now. ${widget.question.explanation}',
                          ha:
                              'An tsallake na yanzu. ${widget.question.explanation}',
                          fr:
                              'Ignore pour le moment. ${widget.question.explanation}')
                      : (_isCorrect ?? false)
                          ? language.tr(
                              en: 'Correct. ${widget.question.explanation}',
                              ha: 'Daidai ne. ${widget.question.explanation}',
                              fr: 'Correct. ${widget.question.explanation}')
                          : language.tr(
                              en: 'Not quite. ${widget.question.explanation}',
                              ha: 'Ba haka ba. ${widget.question.explanation}',
                              fr: 'Pas tout a fait. ${widget.question.explanation}'),
                  style: theme.textTheme.bodySmall?.copyWith(height: 1.5),
                ),
              ),
            const SizedBox(height: 12),
            Row(
              children: <Widget>[
                Expanded(
                  child: AppButton.secondary(
                    onPressed: _revealed
                        ? null
                        : () async {
                            await ref
                                .read(learningProvider.notifier)
                                .skipQuestion(
                                  lessonId: widget.lessonId,
                                  questionId: widget.question.id,
                                );
                            setState(() {
                              _skipped = true;
                              _revealed = true;
                              _isCorrect = null;
                            });
                          },
                    child: Text(
                        language.tr(en: 'Skip', ha: 'Tsallake', fr: 'Ignorer')),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: AppButton.primary(
                    onPressed: _revealed
                        ? null
                        : () async {
                            if (_selectedIndex == null) {
                              ScaffoldMessenger.of(context).showSnackBar(
                                SnackBar(
                                    content: Text(language.tr(
                                        en: 'Choose an answer or skip the question.',
                                        ha: 'Zaɓi amsa ko tsallake tambayar.',
                                        fr: 'Choisissez une reponse ou ignorez la question.'))),
                              );
                              return;
                            }
                            final bool correct = _selectedIndex ==
                                widget.question.correctOptionIndex;
                            await ref
                                .read(learningProvider.notifier)
                                .recordAnswer(
                                  lessonId: widget.lessonId,
                                  questionId: widget.question.id,
                                  correct: correct,
                                );
                            setState(() {
                              _skipped = false;
                              _isCorrect = correct;
                              _revealed = true;
                            });
                          },
                    child: Text(_revealed
                        ? language.tr(
                            en: 'Checked', ha: 'An Duba', fr: 'Verifie')
                        : language.tr(
                            en: 'Check answer',
                            ha: 'Duba Amsa',
                            fr: 'Verifier la reponse')),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

class _MiniMeta extends StatelessWidget {
  const _MiniMeta({
    required this.text,
    required this.color,
  });

  final String text;
  final Color color;

  @override
  Widget build(BuildContext context) {
    final ThemeData theme = Theme.of(context);
    final bool isDark = theme.brightness == Brightness.dark;
    final Color background = isDark
        ? Color.alphaBlend(color.withOpacity(0.24), theme.colorScheme.surface)
        : color;
    final Color foreground =
        isDark ? theme.colorScheme.onSurface : const Color(0xFF284231);

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
      decoration: BoxDecoration(
        color: background,
        borderRadius: BorderRadius.circular(999),
        border: Border.all(
            color: isDark ? color.withOpacity(0.44) : color.withOpacity(0.85)),
      ),
      child: Text(
        text,
        style: theme.textTheme.labelMedium?.copyWith(
          color: foreground,
          fontWeight: FontWeight.w700,
        ),
      ),
    );
  }
}

class _ChecklistTile extends StatelessWidget {
