/// Looks up a lesson by id (e.g. for deep-linking from a notification).
LearningLesson? findLearningLessonById(String id) {
  for (final LearningLesson lesson in _learningLessons) {
    if (lesson.id == id) {
      return lesson;
    }
  }
  return null;
}

